//! Niche-optimized index newtypes and typed vectors with a fixed capacity.
//!
//! Refer to AST and IR nodes through `u32` newtypes stored in `IndexVec`s instead of
//! pointers or hash maps: an index is 4 bytes instead of 8, lookups are a bounds check plus an
//! offset, and the type system stops an `ItemId` from indexing the function table.
//!
//! Indices generated by [`newtype_index!`](crate::newtype_index) store the value plus one in
//! a [`NonZeroU32`](core::num::NonZeroU32), so `u32::MAX` is never a valid index and `Option<Id>`
//! is still 4 bytes:
//!
//! ```
//! vulcan::newtype_index! {
//!     /// Identifies a function.
//!     pub struct FnId;
//! }
//!
//! assert_eq!(size_of::<Option<FnId>>(), 4);
//!
//! let mut fns = vulcan::index::IndexVec::<FnId, &str>::with_capacity(16);
//! let main = fns.push("main");
//! assert_eq!(fns[main], "main");
//! assert_eq!(fns.len(), 1);
//! ```

use crate::convert::{u32_from_usize, usize_from_u32};
use core::{fmt, marker::PhantomData, ops, slice};

/// A typed index into an [`IndexVec`].
pub trait TypedIndex: Copy + Eq + Ord + fmt::Debug + 'static {
    /// Creates an index from a `usize`.
    ///
    /// # Panics
    ///
    /// Panics if `index` is out of range for the index type.
    #[must_use = "the index is the only result"]
    fn from_usize(index: usize) -> Self;

    /// Returns the index as a `usize`, to index a slice.
    #[must_use = "the position is the only result"]
    fn index(self) -> usize;
}

/// Defines `u32` index newtypes with a niche, so `Option<Self>` is 4 bytes.
///
/// The type implements [`TypedIndex`], [`CacheKey`](crate::cache::CacheKey) (with a dense cache),
/// `Copy`, `Eq`, `Ord`, `Hash` and `Debug`, and exposes
/// `from_u32`, `try_from_u32`, `as_u32`, `as_usize`, `INDEX_MAX` and `MAX`.
#[macro_export]
macro_rules! newtype_index {
    ($($(#[$attr:meta])* $vis:vis struct $name:ident;)*) => {$(
        $(#[$attr])*
        // The stored value is the index plus one, which keeps the order of the indices: the
        // derived comparisons are the comparisons of the indices.
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        $vis struct $name(::core::num::NonZeroU32);

        impl $name {
            /// The largest representable index.
            $vis const INDEX_MAX: u32 = u32::MAX - 1;

            /// The largest index value, [`INDEX_MAX`](Self::INDEX_MAX).
            $vis const MAX: Self = Self(::core::num::NonZeroU32::MAX);

            /// Creates an index, or returns `None` if `value` is `u32::MAX`.
            #[inline]
            #[must_use = "the index is the only result"]
            $vis const fn try_from_u32(value: u32) -> ::core::option::Option<Self> {
                if value > Self::INDEX_MAX {
                    assert!(value == u32::MAX, "only `u32::MAX` lies above `INDEX_MAX`");
                    return ::core::option::Option::None;
                }
                // Does not saturate: the check above leaves room for the one added.
                let index = Self(::core::num::NonZeroU32::MIN.saturating_add(value));
                assert!(index.as_u32() == value, "the index round-trips");
                ::core::option::Option::Some(index)
            }

            /// Creates an index.
            ///
            /// # Panics
            ///
            /// Panics if `value` is `u32::MAX`.
            #[inline]
            #[must_use = "the index is the only result"]
            #[track_caller]
            $vis const fn from_u32(value: u32) -> Self {
                assert!(value <= Self::INDEX_MAX, "index out of range");
                let ::core::option::Option::Some(index) = Self::try_from_u32(value) else {
                    // Unreachable: the assertion above rules out the only value without an index.
                    return Self::MAX;
                };
                assert!(index.as_u32() == value, "the index round-trips");
                index
            }

            /// Returns the index as a `u32`.
            #[inline]
            #[must_use = "the value is the only result"]
            $vis const fn as_u32(self) -> u32 {
                // Cannot underflow: the stored value is at least one.
                let value = self.0.get() - 1;
                assert!(value <= Self::INDEX_MAX, "`u32::MAX` is never an index");
                value
            }

            /// Returns the index as a `usize`.
            #[inline]
            #[must_use = "the value is the only result"]
            $vis const fn as_usize(self) -> usize {
                let value = self.as_u32();
                let converted = $crate::convert::usize_from_u32(value);
                assert!(converted < $crate::convert::usize_from_u32(u32::MAX), "below `u32::MAX`");
                converted
            }
        }

        impl ::core::fmt::Debug for $name {
            fn fmt(&self, formatter: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                write!(formatter, "{}({})", stringify!($name), self.as_u32())
            }
        }

        impl $crate::cache::CacheKey for $name {
            type Cache<Value: Copy> = $crate::cache::DenseCache<Self, Value>;
        }

        // The niche is the reason the type exists, so its loss fails the build.
        const _: () = assert!(
            ::core::mem::size_of::<::core::option::Option<$name>>() == 4,
            "`Option` of an index must stay 4 bytes",
        );
        const _: () = assert!(
            ::core::mem::size_of::<$name>() == 4,
            "an index is 4 bytes",
        );
        const _: () = assert!($name::MAX.as_u32() == $name::INDEX_MAX, "`MAX` holds `INDEX_MAX`");
        const _: () = assert!($name::from_u32(0).as_u32() == 0, "the first index is zero");
        const _: () = assert!($name::try_from_u32(u32::MAX).is_none(), "the niche has no index");
        const _: () = assert!($name::INDEX_MAX == u32::MAX - 1, "one value is kept for the niche");
        // The derived comparisons compare the stored values, so they must sort like the indices.
        const _: () = assert!($name::from_u32(0).0.get() < $name::MAX.0.get(), "the order is kept");

        impl $crate::index::TypedIndex for $name {
            #[inline]
            #[track_caller]
            fn from_usize(index: usize) -> Self {
                let index_max = $crate::convert::usize_from_u32(Self::INDEX_MAX);
                assert!(index <= index_max, "index out of range");
                let created = Self::from_u32($crate::convert::u32_from_usize(index));
                assert!(created.as_usize() == index, "the index round-trips");
                created
            }

            #[inline]
            fn index(self) -> usize {
                let position = self.as_usize();
                let position_max = $crate::convert::usize_from_u32(Self::INDEX_MAX);
                assert!(position <= position_max, "`u32::MAX` is never an index");
                position
            }
        }
    )*};
}

/// Ties a container to its index type without owning an `Index`, so the container stays `Send`,
/// `Sync` and covariant whatever `Index` is.
type IndexMarker<Index> = PhantomData<fn() -> Index>;

/// A `Vec<Value>` indexed by `Index` instead of `usize`, with a capacity fixed at construction.
///
/// The whole capacity is allocated up front and a push never reallocates: pushing past the
/// capacity is a broken limit, which is a programmer error, and it panics.
#[derive(PartialEq, Eq)]
pub struct IndexVec<Index, Value> {
    /// The elements, allocated with room for `capacity` of them.
    raw: Vec<Value>,
    /// The number of elements the vector may hold, which it never exceeds.
    capacity: u32,
    /// The index type.
    _index: IndexMarker<Index>,
}

impl<Index: TypedIndex, Value> IndexVec<Index, Value> {
    /// Creates an empty vector and allocates room for `capacity` elements.
    ///
    /// # Panics
    ///
    /// Panics if the index type cannot represent the last index below `capacity`.
    #[inline]
    #[must_use = "a new vector does nothing until used"]
    pub fn with_capacity(capacity: u32) -> Self {
        let raw = Vec::with_capacity(usize_from_u32(capacity));
        assert!(raw.capacity() >= usize_from_u32(capacity), "the allocation covers the capacity");
        assert!(raw.is_empty(), "a new vector is empty");
        if let Some(last) = capacity.checked_sub(1) {
            let last_index = Index::from_usize(usize_from_u32(last));
            assert_eq!(
                last_index.index(),
                usize_from_u32(last),
                "the index type reaches every slot"
            );
        }
        Self { raw, capacity, _index: PhantomData }
    }

    /// Appends `value` and returns its index.
    ///
    /// # Panics
    ///
    /// Panics if the vector already holds `capacity` elements.
    #[inline]
    #[track_caller]
    pub fn push(&mut self, value: Value) -> Index {
        let count = self.len();
        assert!(count < self.capacity, "the index vector is full");
        let index = Index::from_usize(usize_from_u32(count));
        assert!(index.index() < usize_from_u32(self.capacity), "a new index lies in the capacity");
        let allocation_before = self.raw.capacity();
        self.raw.push(value);
        assert_eq!(self.raw.capacity(), allocation_before, "a push never reallocates");
        // An index is 0-based and a count 1-based: the new element's index plus one is the length.
        assert_eq!(index.index() + 1, self.raw.len(), "the pushed index is the last one");
        index
    }

    /// Returns the index the next [`push`](Self::push) will return.
    ///
    /// # Panics
    ///
    /// Panics if the vector holds `u32::MAX` elements, which has no index.
    #[inline]
    #[must_use = "the index is the only result"]
    #[track_caller]
    pub fn next_index(&self) -> Index {
        let count = self.len();
        assert!(count <= self.capacity, "the next index is at most the capacity");
        let index = Index::from_usize(usize_from_u32(count));
        assert_eq!(index.index(), usize_from_u32(count), "the next index is the element count");
        index
    }

    /// Returns the number of elements.
    ///
    /// # Panics
    ///
    /// Panics only if an invariant of the vector is broken, which is a bug in this module.
    #[inline]
    #[must_use = "the count is the only result"]
    pub const fn len(&self) -> u32 {
        let count = u32_from_usize(self.raw.len());
        assert!(count <= self.capacity, "the length stays within the capacity");
        count
    }

    /// Returns the number of elements the vector may hold.
    ///
    /// # Panics
    ///
    /// Panics only if an invariant of the vector is broken, which is a bug in this module.
    #[inline]
    #[must_use = "the capacity is the only result"]
    pub const fn capacity(&self) -> u32 {
        assert!(self.raw.len() <= usize_from_u32(self.capacity), "the length stays bounded");
        self.capacity
    }

    /// Returns `true` if the vector has no elements.
    ///
    /// # Panics
    ///
    /// Panics only if the vector grew past its capacity, which is a bug in this module.
    #[inline]
    #[must_use = "the answer is the only result"]
    pub const fn is_empty(&self) -> bool {
        assert!(self.raw.len() <= usize_from_u32(self.capacity), "the length stays bounded");
        self.raw.is_empty()
    }

    /// Returns the element at `index`, or `None` if the vector does not reach it yet.
    ///
    /// # Panics
    ///
    /// Panics if `index` is at or beyond the capacity: no vector of this capacity produced it.
    #[inline]
    #[must_use = "the element is the only result"]
    #[track_caller]
    pub fn get(&self, index: Index) -> Option<&Value> {
        assert!(
            index.index() < usize_from_u32(self.capacity),
            "index beyond the capacity of the vector"
        );
        self.raw.get(index.index())
    }

    /// Returns the element at `index` mutably, or `None` if the vector does not reach it yet.
    ///
    /// # Panics
    ///
    /// Panics if `index` is at or beyond the capacity: no vector of this capacity produced it.
    #[inline]
    #[must_use = "the element is the only result"]
    #[track_caller]
    pub fn get_mut(&mut self, index: Index) -> Option<&mut Value> {
        assert!(
            index.index() < usize_from_u32(self.capacity),
            "index beyond the capacity of the vector"
        );
        self.raw.get_mut(index.index())
    }

    /// Returns the elements as a plain slice.
    ///
    /// # Panics
    ///
    /// Panics only if an invariant of the vector is broken, which is a bug in this module.
    #[inline]
    #[must_use = "the slice is the only result"]
    pub fn as_raw_slice(&self) -> &[Value] {
        let elements = self.raw.as_slice();
        assert!(elements.len() <= usize_from_u32(self.capacity), "the length stays bounded");
        elements
    }

    /// Iterates over the elements.
    ///
    /// # Panics
    ///
    /// Panics only if an invariant of the vector is broken, which is a bug in this module.
    #[inline]
    pub fn iter(&self) -> slice::Iter<'_, Value> {
        self.as_raw_slice().iter()
    }

    /// Iterates over `(index, element)` pairs.
    ///
    /// # Panics
    ///
    /// Panics only if an invariant of the vector is broken, which is a bug in this module.
    #[inline]
    #[must_use = "iterators are lazy and do nothing unless consumed"]
    pub fn iter_enumerated(&self) -> impl ExactSizeIterator<Item = (Index, &Value)> {
        self.as_raw_slice()
            .iter()
            .enumerate()
            .map(|(position, element)| (Index::from_usize(position), element))
    }

    /// Returns every valid index, in order.
    ///
    /// # Panics
    ///
    /// Panics only if an invariant of the vector is broken, which is a bug in this module.
    #[inline]
    #[must_use = "iterators are lazy and do nothing unless consumed"]
    pub fn indices(&self) -> impl ExactSizeIterator<Item = Index> + use<Index, Value> {
        (0..self.as_raw_slice().len()).map(Index::from_usize)
    }
}

impl<Index: TypedIndex, Value: Clone> Clone for IndexVec<Index, Value> {
    /// Copies the elements into a new allocation of the same capacity, which a derived clone
    /// would shrink to the length.
    fn clone(&self) -> Self {
        let mut copy = Self::with_capacity(self.capacity);
        copy.raw.extend_from_slice(&self.raw);
        assert_eq!(copy.raw.len(), self.raw.len(), "every element is copied");
        assert!(copy.raw.capacity() >= usize_from_u32(self.capacity), "the allocation is kept");
        assert_eq!(copy.capacity, self.capacity, "the capacity is kept");
        copy
    }
}

impl<Index: TypedIndex, Value: fmt::Debug> fmt::Debug for IndexVec<Index, Value> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        assert!(self.len() <= self.capacity, "the length stays within the capacity");
        formatter.debug_map().entries(self.iter_enumerated()).finish()
    }
}

impl<Index: TypedIndex, Value> ops::Index<Index> for IndexVec<Index, Value> {
    type Output = Value;

    #[inline]
    #[track_caller]
    fn index(&self, index: Index) -> &Value {
        let position = index.index();
        // Checked apart from the length, so an index from a larger vector is told from one that
        // this vector has not reached yet.
        assert!(
            position < usize_from_u32(self.capacity),
            "index beyond the capacity of the vector"
        );
        assert!(position < self.raw.len(), "index past the end of the vector");
        &self.raw[position]
    }
}

impl<Index: TypedIndex, Value> ops::IndexMut<Index> for IndexVec<Index, Value> {
    #[inline]
    #[track_caller]
    fn index_mut(&mut self, index: Index) -> &mut Value {
        let position = index.index();
        assert!(
            position < usize_from_u32(self.capacity),
            "index beyond the capacity of the vector"
        );
        assert!(position < self.raw.len(), "index past the end of the vector");
        &mut self.raw[position]
    }
}

impl<'vector, Index: TypedIndex, Value> IntoIterator for &'vector IndexVec<Index, Value> {
    type Item = &'vector Value;
    type IntoIter = slice::Iter<'vector, Value>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    crate::newtype_index! {
        /// Test index.
        struct NodeId;
        /// Second test index, to check the macro accepts several types.
        struct EdgeId;
    }

    /// Checks the layout promise of the macro: an index and an `Option` of one are 4 bytes, for
    /// every type of a multi-type invocation.
    #[test]
    fn option_uses_the_niche() {
        assert_eq!(size_of::<NodeId>(), 4);
        assert_eq!(size_of::<Option<NodeId>>(), 4);
        assert_eq!(size_of::<Option<EdgeId>>(), 4);
    }

    /// Round-trips the first, a middle and the last valid value through `u32`, and compares and
    /// formats indices, to check that the stored offset never leaks out.
    #[test]
    fn round_trips_and_orders_by_value() {
        for value in [0, 1, 42, NodeId::INDEX_MAX] {
            assert_eq!(NodeId::from_u32(value).as_u32(), value);
            assert_eq!(NodeId::from_usize(usize_from_u32(value)).index(), usize_from_u32(value));
        }
        // The last valid value and the first invalid one, side by side.
        assert!(NodeId::try_from_u32(NodeId::INDEX_MAX).is_some());
        assert!(NodeId::try_from_u32(u32::MAX).is_none());
        assert_eq!(NodeId::MAX.as_u32(), NodeId::INDEX_MAX);
        assert_eq!(NodeId::MAX.as_usize(), usize_from_u32(NodeId::INDEX_MAX));
        assert!(NodeId::from_u32(1) < NodeId::from_u32(2));
        assert!(NodeId::from_u32(0) < NodeId::MAX);
        assert_eq!(format!("{:?}", NodeId::from_u32(7)), "NodeId(7)");
    }

    /// Creates an index from `u32::MAX`, the one value without a niche, which must panic.
    #[test]
    #[should_panic(expected = "index out of range")]
    fn rejects_u32_max() {
        let _index = NodeId::from_u32(u32::MAX);
    }

    /// Creates an index from a `usize` above `u32::MAX`, which must panic instead of wrapping.
    #[test]
    #[cfg(target_pointer_width = "64")]
    #[should_panic(expected = "index out of range")]
    fn rejects_usize_above_u32() {
        let _index = NodeId::from_usize(usize::MAX);
    }

    /// Fills a vector of capacity two, then reads and writes it through every accessor, and
    /// probes the first index past the end, which is inside the capacity of a larger vector.
    #[test]
    fn index_vec_basics() {
        let mut letters = IndexVec::<NodeId, char>::with_capacity(3);
        assert!(letters.is_empty());
        let first = letters.push('a');
        let second = letters.push('b');
        assert_eq!((first.as_u32(), second.as_u32()), (0, 1));
        letters[second] = 'c';
        assert_eq!(letters.get(second), Some(&'c'));
        assert_eq!(letters.get(NodeId::from_u32(2)), None, "one past the end is absent");
        if let Some(letter) = letters.get_mut(first) {
            *letter = 'z';
        }
        assert_eq!(letters[first], 'z');
        assert_eq!(
            letters
                .iter_enumerated()
                .map(|(index, letter)| (index.as_u32(), *letter))
                .collect::<Vec<_>>(),
            [(0, 'z'), (1, 'c')]
        );
        assert_eq!(letters.indices().collect::<Vec<_>>(), [first, second]);
        assert_eq!(letters.next_index().as_u32(), 2);
        assert_eq!((letters.len(), letters.capacity()), (2, 3));
        assert_eq!(letters.as_raw_slice(), ['z', 'c']);
        assert_eq!(format!("{letters:?}"), "{NodeId(0): 'z', NodeId(1): 'c'}");
    }

    /// Fills a vector to its capacity, and checks that a clone keeps both the elements and the
    /// room left, so it can be pushed to as far as the original.
    #[test]
    fn index_vec_fills_to_capacity_and_clones_with_it() {
        let mut numbers = IndexVec::<NodeId, u32>::with_capacity(2);
        let _first = numbers.push(10);
        let copy = numbers.clone();
        assert_eq!(copy, numbers);
        assert_eq!(copy.capacity(), 2);
        let last = numbers.push(20);
        assert_eq!(last.as_u32(), 1, "the push at capacity minus one is accepted");
        assert_eq!(numbers.len(), numbers.capacity());
        numbers[last] += 1;
        assert_eq!((&numbers).into_iter().copied().collect::<Vec<_>>(), [10, 21]);
        assert_eq!(numbers.iter().count(), 2);
    }

    /// Pushes one element past the capacity, which must panic rather than reallocate.
    #[test]
    #[should_panic(expected = "the index vector is full")]
    fn index_vec_rejects_a_push_past_capacity() {
        let mut numbers = IndexVec::<NodeId, u32>::with_capacity(1);
        let _first = numbers.push(1);
        let _second = numbers.push(2);
    }

    /// Pushes into a vector of capacity zero, the empty boundary, which must panic.
    #[test]
    #[should_panic(expected = "the index vector is full")]
    fn index_vec_of_capacity_zero_rejects_every_push() {
        let mut numbers = IndexVec::<NodeId, u32>::with_capacity(0);
        let _first = numbers.push(1);
    }

    /// Looks up an index equal to the capacity, which no vector of that capacity produced.
    #[test]
    #[should_panic(expected = "index beyond the capacity of the vector")]
    fn index_vec_rejects_an_index_beyond_capacity() {
        let numbers = IndexVec::<NodeId, u32>::with_capacity(2);
        let _missing = numbers.get(NodeId::from_u32(2));
    }

    /// Indexes one past the last element, which must panic with the vector's message.
    #[test]
    #[should_panic(expected = "index past the end of the vector")]
    fn index_vec_rejects_indexing_past_the_end() {
        let numbers = IndexVec::<NodeId, u32>::with_capacity(2);
        let _missing = numbers[NodeId::from_u32(0)];
    }
}
